"""Testes de navegador do site contra o Supabase simulado (harness.py), com o esquema normalizado.
Rode com ./rodar_testes.sh (sobe o mock e o site de teste). t1.py precisa ter rodado antes (cria a conta da Ana)."""
import json, os, re, urllib.request, datetime
from playwright.sync_api import sync_playwright
URL = 'http://127.0.0.1:8765/'; M = 'http://127.0.0.1:8766'
SHOT = os.environ.get('SHOT_DIR', '/tmp/')
UUID = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
UUIDANY = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
def mock(path): return json.loads(urllib.request.urlopen(M + path).read() or b'null')
def rows(t, email=None): return mock('/__mock/rows?t=' + t + ('&email=' + email if email else ''))
def db_errors(): return [x for x in mock('/__mock/log') if x[0] == 'ERRO']
ok = [0, 0]
def chk(name, cond, extra=''):
    ok[0 if cond else 1] += 1; print(('  OK   ' if cond else '  FALHA ') + name + (' ' + str(extra) if extra != '' else ''))
def login(pg, email, pw, manter=False):
    pg.wait_for_selector('#f-entrar'); pg.fill('#a-email', email); pg.fill('#a-senha', pw)
    if manter: pg.check('#a-manter')
    pg.locator('#f-entrar button[type=submit]').click()
def logged(pg, t=8000): pg.wait_for_selector('#gate', state='hidden', timeout=t)
def tab(pg, name): pg.locator('[data-action="tab"][data-tab="%s"]' % name).click(); pg.wait_for_timeout(200)
def saved(pg):
    for _ in range(40):
        if pg.locator('#foot').count() and pg.locator('#foot').inner_text().startswith('Dados privados'): return True
        pg.wait_for_timeout(150)
    return False
def add_company(pg, nome, valor=None):
    tab(pg, 'empresas'); pg.locator('#fab').click(); pg.wait_for_selector('#f-company')
    pg.fill('#f-company [name=nome]', nome)
    if valor: pg.fill('#c-val', valor)
    pg.locator('#f-company button[type=submit]').click(); pg.wait_for_timeout(300)
def open_menu_item(pg, go):
    pg.locator('[data-action="open-menu"]').click(); pg.wait_for_timeout(250); pg.locator('[data-go="%s"]' % go).click(); pg.wait_for_timeout(250)
def confirm_delete(pg):
    pg.locator('.sheet [data-action="ask"]').click(); pg.locator('.sheet .confirm:not([hidden]) .btn.danger').click(); pg.wait_for_timeout(300)
def br(d): return d.strftime('%d/%m/%Y')

