    b = p.chromium.launch(executable_path=os.environ.get('CHROME_PATH') or None)
    errs = []
    def newctx(**k): return b.new_context(viewport={'width': 390, 'height': 844}, has_touch=True, accept_downloads=True, **k)
    def newpage(c):
        pg = c.new_page(); pg.on('pageerror', lambda e: errs.append(str(e)))
        pg.on('console', lambda m: errs.append('console:' + m.text) if m.type == 'error' and 'fonts.g' not in m.text and 'status of 40' not in m.text and 'status of 50' not in m.text else None)
        return pg
    ctx = newctx(); pg = newpage(ctx)
    print('A) entrar com a conta criada antes'); pg.goto(URL); login(pg, 'ana@teste.com', 'senha-segura-1'); logged(pg)
    chk('mostra exemplos e nada salvo', pg.locator('#foot').inner_text().startswith('Dados de exemplo'))
    print('B) primeira gravacao'); add_company(pg, 'Clinica Teste'); chk('rodape: salvo na conta', saved(pg), pg.locator('#foot').inner_text())
    pr = rows('profiles'); co = rows('companies'); pa = rows('patients'); vi = rows('visits')
    chk('perfil criado e iniciado', len(pr) == 1 and pr[0]['iniciado'] is True, pr[0]['nome'] if pr else '')
    chk('empresa nova no servidor, com colunas proprias', [r['nome'] for r in co] == ['Clinica Teste'] and 'data' not in co[0], co)
    chk('id da empresa e uuid v4', all(UUID.match(r['id']) for r in co), [r['id'] for r in co])
    chk('dados de exemplo NAO vao para o banco', len(pa) == 0 and len(vi) == 0 and len(co) == 1, (len(co), len(pa), len(vi)))
    chk('nenhum erro do banco', db_errors() == [], db_errors())
    print('C) recarregar a pagina'); pg.reload(); logged(pg); pg.wait_for_timeout(300); tab(pg, 'empresas')
    chk('dados vieram do servidor', ('Clinica Teste' in pg.locator('#view').inner_text()) and not pg.locator('#foot').inner_text().startswith('Dados de exemplo'))
    print('D) gravacao incremental'); mock('/__mock/clearlog')
    open_menu_item(pg, 'perfil'); pg.fill('#pf-tel', '(11) 90000-0000'); pg.locator('#f-perfil button[type=submit]').click(); saved(pg); pg.wait_for_timeout(300)
