    print('N) manter conectado'); c2 = newctx(); p2 = newpage(c2); p2.goto(URL); login(p2, 'ana@teste.com', 'senha-segura-1', manter=True); logged(p2)
    chk('sessao em localStorage', p2.evaluate("!!localStorage.getItem('cuidar-em-casa:sb')"))
